//Generated by AI
using UnityEngine;
using UnityEngine.SceneManagement;

public class PauseMenuController : MonoBehaviour
{
    [Header("Menus")]
    [SerializeField] private GameObject pauseMenu;
    [SerializeField] private GameObject mainMenu;
    [SerializeField] private GameObject settingsMenu;

    [Header("Audio")]
    [SerializeField] private AudioClip openMenuClip;
    [SerializeField] private AudioClip closeMenuClip;

    [SerializeField] private AudioSource menuMusic;
    [SerializeField] private AudioSource playButtonSound;
    [SerializeField] private AudioSource pollutedEnvironmentAudio;

    [Header("Menu Background")]
    [SerializeField] private GameObject mainMenuBackground;

    private AudioSource audioSource;
    private Animator mainMenuAnimator;

    public static bool GameStarted = false;

    private bool openedFromPauseMenu = false;

    // Restart management
    private static bool restartIntoGameplay = false;
    private bool isRestarting = false;


    private void Start()
    {
        audioSource = GetComponent<AudioSource>();

        if (mainMenu != null)
        {
            mainMenuAnimator = mainMenu.GetComponent<Animator>();
        }

        // Check whether the scene was reloaded through Restart
        bool shouldStartGameplay = restartIntoGameplay;

        // Reset the restart flag after reading it
        restartIntoGameplay = false;

        GameStarted = shouldStartGameplay;

        // Start gameplay normally after a restart
        // Otherwise, initialize the main menu
        Time.timeScale = shouldStartGameplay ? 1f : 0f;

        if (pollutedEnvironmentAudio != null)
        {
            pollutedEnvironmentAudio.Stop();
        }

        if (mainMenuAnimator != null)
        {
            mainMenuAnimator.enabled = false;
        }

        // Initialize menu visibility
        if (mainMenu != null)
        {
            mainMenu.SetActive(!shouldStartGameplay);
        }

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(false);
        }

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(false);
        }

        UpdateMainMenuBackground();

        // Initialize the correct audio for each situation
        if (shouldStartGameplay)
        {
            if (menuMusic != null)
            {
                menuMusic.Stop();
            }

            if (pollutedEnvironmentAudio != null)
            {
                pollutedEnvironmentAudio.Play();
            }
        }
        else
        {
            if (menuMusic != null && !menuMusic.isPlaying)
            {
                menuMusic.Play();
            }
        }
    }


    // BACKGROUND
    private void UpdateMainMenuBackground()
    {
        if (mainMenuBackground == null)
            return;

        bool shouldShowBackground = !GameStarted;

        if (mainMenuBackground.activeSelf != shouldShowBackground)
        {
            mainMenuBackground.SetActive(shouldShowBackground);
        }
    }

    // AUDIO
    private void PlayOpenSound()
    {
        if (audioSource != null && openMenuClip != null)
        {
            audioSource.PlayOneShot(openMenuClip);
        }
    }

    private void PlayCloseSound()
    {
        if (audioSource != null && closeMenuClip != null)
        {
            audioSource.PlayOneShot(closeMenuClip);
        }
    }

    // GAME
    public void StartGame()
    {
        GameStarted = true;
        Time.timeScale = 1f;

        UpdateMainMenuBackground();

        if (playButtonSound != null)
        {
            playButtonSound.Play();
        }

        if (menuMusic != null)
        {
            menuMusic.Stop();
        }

        if (pollutedEnvironmentAudio != null)
        {
            pollutedEnvironmentAudio.Play();
        }

        if (mainMenu != null)
        {
            mainMenu.SetActive(false);
        }
    }

    // MAIN MENU
    public void OpenMainMenu()
    {
        PlayOpenSound();

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(false);
        }

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(false);
        }

        if (mainMenu != null)
        {
            mainMenu.SetActive(true);
        }

        UpdateMainMenuBackground();
    }

    public void CloseMainMenu()
    {
        if (!GameStarted)
            return;

        PlayCloseSound();

        if (mainMenu != null)
        {
            mainMenu.SetActive(false);
        }
    }

    // QUIT GAME
    public void QuitGame()
    {
        #if UNITY_EDITOR
                UnityEditor.EditorApplication.isPlaying = false;
        #else
                Application.Quit();
        #endif
    }

    // SETTINGS MENU
    public void OpenSettingsFromMain()
    {
        PlayOpenSound();

        openedFromPauseMenu = false;
        UpdateMainMenuBackground();

        if (mainMenu != null)
        {
            mainMenu.SetActive(false);
        }

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(true);
        }
    }

    public void OpenSettingsFromPause()
    {
        PlayOpenSound();

        openedFromPauseMenu = true;
        UpdateMainMenuBackground();

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(false);
        }

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(true);
        }
    }

    public void CloseSettingsMenu()
    {
        PlayCloseSound();

        if (settingsMenu != null)
        {
            settingsMenu.SetActive(false);
        }

        UpdateMainMenuBackground();

        if (openedFromPauseMenu)
        {
            if (pauseMenu != null)
            {
                pauseMenu.SetActive(true);
            }
        }
        else
        {
            if (mainMenu != null)
            {
                mainMenu.SetActive(true);
            }
        }
    }

    // PAUSE MENU
    public void OpenPauseMenu()
    {
        if (!GameStarted)
            return;

        PlayOpenSound();
        UpdateMainMenuBackground();

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(true);
        }
    }

    public void ClosePauseMenu()
    {
        PlayCloseSound();
        UpdateMainMenuBackground();

        if (pauseMenu != null)
        {
            pauseMenu.SetActive(false);
        }
    }


    public void RestartGame()
    {
        if (isRestarting)
            return;

        // Get the currently active scene
        Scene currentScene = SceneManager.GetActiveScene();

        if (!currentScene.IsValid() || currentScene.buildIndex < 0)
        {
            Debug.LogError(
                "Restart failed: The current scene is not included " +
                "in the active Build Profile."
            );

            return;
        }

        isRestarting = true;

        // Tell the next scene initialization to start gameplay
        restartIntoGameplay = true;

        GameStarted = true;

        // Make sure the game is not paused during the reload
        Time.timeScale = 1f;

        Debug.Log("Restarting level: " + currentScene.name);

        // Reload the current level
        SceneManager.LoadScene(currentScene.buildIndex);
    }
}